const tracks=[{id:'riddim',name:'Riddim Riot',file:null},{id:'desde',name:'Desde Cero',file:null},{id:'buho',name:'B.U.H.O',file:null},{id:'conqueror',name:'Conqueror',file:null}];const $=s=>document.querySelector(s),audio=$('#audio');let current=0,random=false,timer;
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>t.classList.remove('show'),3500)}
function select(id){current=tracks.findIndex(t=>t.id===id);const t=tracks[current];$('#name').textContent=t.name.toUpperCase();audio.pause();audio.removeAttribute('src');audio.load();$('#toggle').textContent='▶';$('#elapsed').textContent='00:00';$('#duration').textContent='00:00';return t}
function play(id){const t=select(id);if(!t.file){toast('El audio original de '+t.name+' todavía no está cargado.');return}audio.src=t.file;audio.play().catch(()=>toast('No se pudo reproducir el archivo.'))}
document.querySelectorAll('[data-play]').forEach(b=>b.addEventListener('click',()=>play(b.dataset.play)));document.querySelectorAll('[data-download]').forEach(b=>b.addEventListener('click',()=>{const t=tracks.find(x=>x.id===b.dataset.download);if(!t.file){toast('El MP3 de '+t.name+' todavía no está disponible para descargar.');return}const a=document.createElement('a');a.href=t.file;a.download=t.name+'.mp3';a.click()}));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.querySelectorAll('.track').forEach(x=>x.hidden=b.dataset.filter!=='all'&&x.dataset.type!==b.dataset.filter)}));$('#all').addEventListener('click',()=>{$('[data-filter="all"]').click();$('#grid').scrollIntoView({behavior:'smooth'})});
$('#toggle').addEventListener('click',()=>{if(!audio.getAttribute('src')){play(tracks[current].id);return}audio.paused?audio.play():audio.pause()});audio.addEventListener('play',()=>$('#toggle').textContent='Ⅱ');audio.addEventListener('pause',()=>$('#toggle').textContent='▶');function move(d){play(tracks[random?Math.floor(Math.random()*4):(current+d+4)%4].id)}$('#prev').addEventListener('click',()=>move(-1));$('#next').addEventListener('click',()=>move(1));audio.addEventListener('ended',()=>move(1));$('#shuffle').addEventListener('click',()=>{random=!random;$('#shuffle').setAttribute('aria-pressed',String(random));toast(random?'Aleatorio activado':'Aleatorio desactivado')});
const fmt=s=>Number.isFinite(s)?String(Math.floor(s/60)).padStart(2,'0')+':'+String(Math.floor(s%60)).padStart(2,'0'):'00:00';audio.addEventListener('timeupdate',()=>{if(audio.duration){$('#seek').value=audio.currentTime/audio.duration*100;$('#elapsed').textContent=fmt(audio.currentTime);$('#duration').textContent=fmt(audio.duration)}});$('#seek').addEventListener('input',e=>{if(audio.duration)audio.currentTime=audio.duration*e.target.value/100});$('#volume').addEventListener('input',e=>audio.volume=e.target.value/100);audio.volume=.8;
$('#menu').addEventListener('click',()=>{const open=$('#nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open))});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{$('#nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')}));
